diff --git a/batch.go b/batch.go
index f439133a..5ae09af7 100644
--- a/batch.go
+++ b/batch.go
@@ -371,6 +371,17 @@ type batchInternal struct {

 	commitErr error

+	// Fields used for tracking Sync commit durability and BatchDurableInfo.
+	commitCorrelationID uint64
+	durableJobID        int
+	durableSeqNum       base.SeqNum
+	durableBatchSize    int
+	durableKeyCount     uint32
+	applyDuration       time.Duration
+	syncStartMono       crtime.Mono
+	syncWAL             bool
+	durableRecorded     bool
+
 	// Position bools together to reduce the sizeof the struct.

 	// ingestedSSTBatch indicates that the batch contains one or more key kinds
@@ -1700,14 +1711,52 @@ func (b *Batch) Reader() batchrepr.Reader {
 	return batchrepr.Read(b.data)
 }

+func (b *Batch) completeDurability(syncDuration time.Duration, err error) {
+	if !b.syncWAL || b.durableRecorded || b.durableJobID <= 0 {
+		return
+	}
+	b.durableRecorded = true
+	db := b.db
+	if db == nil {
+		return
+	}
+	if syncDuration <= 0 {
+		syncDuration = time.Nanosecond
+	}
+	applyDuration := b.applyDuration
+	if applyDuration <= 0 {
+		applyDuration = time.Nanosecond
+	}
+	info := BatchDurableInfo{
+		JobID:         b.durableJobID,
+		SeqNum:        b.durableSeqNum,
+		Err:           err,
+		ApplyDuration: applyDuration,
+		SyncDuration:  syncDuration,
+		CorrelationID: b.commitCorrelationID,
+		BatchSize:     b.durableBatchSize,
+		KeyCount:      b.durableKeyCount,
+	}
+	var cb func(BatchDurableInfo)
+	if db.opts != nil && db.opts.EventListener != nil {
+		cb = db.opts.EventListener.BatchDurable
+	}
+	db.durability.recordCompletion(info, cb)
+}
+
 // SyncWait is to be used in conjunction with DB.ApplyNoSyncWait.
 func (b *Batch) SyncWait() error {
 	now := crtime.NowMono()
 	b.fsyncWait.Wait()
+	waitDuration := now.Elapsed()
+	syncDuration := waitDuration
+	if b.syncStartMono != 0 {
+		syncDuration = b.syncStartMono.Elapsed()
+	}
+	b.completeDurability(syncDuration, b.commitErr)
 	if b.commitErr != nil {
 		b.db = nil // prevent batch reuse on error
 	}
-	waitDuration := now.Elapsed()
 	b.commitStats.CommitWaitDuration += waitDuration
 	b.commitStats.TotalDuration += waitDuration
 	return b.commitErr
